package net.battlespades.ugc;

import java.math.BigInteger;
import java.util.*;
import net.battlespades.world.MetadataDocument;

/** Authoritative multi-mode project, native item names and recovered objective limits. */
public final class UgcProject {
    public static final int MAX_ENTITIES=8192;
    public static final List<String> MODES=List.of("tdm","ctf","dem","mh","oc","tc","vip","zom","dia");
    public record Terrain(String key,String stem,int tag){}
    public static final List<Terrain> TERRAINS=List.of(new Terrain("desert","DesertBaseplate",1),new Terrain("lunar","LunarBaseplate",0),new Terrain("mountain","MountainBaseplate",3),new Terrain("grassland","GrasslandBaseplate",2),new Terrain("temple","TempleBaseplate",4),new Terrain("urban","UrbanBaseplate",5),new Terrain("marsh","MarshBaseplate",2),new Terrain("snowy","SnowyBaseplate",3),new Terrain("water","WaterBaseplate",2));
    private static final List<String> PALETTES=List.of("lunar","desert","grassland","mountain","temple","urban");
    public static Terrain terrain(String value){String n=value.strip().replace('\\','/');n=n.substring(n.lastIndexOf('/')+1);int dot=n.lastIndexOf('.');if(dot>=0)n=n.substring(0,dot);for(var t:TERRAINS)if(t.key.equalsIgnoreCase(n)||t.stem.equalsIgnoreCase(n))return t;throw new IllegalArgumentException("Unknown UGC terrain: "+value);}
    public static String target(String value){String code=value.strip().toLowerCase(Locale.ROOT);code=switch(code){case "zombie"->"zom";case "territory"->"tc";default->code;};if(!MODES.contains(code))throw new IllegalArgumentException("Unsupported UGC target: "+value);return code;}
    public static int modeId(String code){return switch(code.strip().toLowerCase(Locale.ROOT)){case "nor"->0;case "dem"->1;case "zom"->2;case "mh"->3;case "oc"->4;case "dia"->5;case "tdm"->6;case "vip"->7;case "ctf"->8;case "tc"->9;default->modeId(target(code));};}
    public static String modeCode(int id){return switch(id){case 0->"nor";case 1->"dem";case 2->"zom";case 3->"mh";case 4->"oc";case 5->"dia";case 6->"tdm";case 7->"vip";case 8->"ctf";case 9->"tc";default->throw new IllegalArgumentException("Editor-incompatible mode id");};}
    public static int item(Object value){int id;if(value instanceof Number n)id=integer(n);else{String text=String.valueOf(value).strip();try{id=Integer.parseInt(text);}catch(NumberFormatException e){id=-1;for(int i=0;i<UgcCatalog.ITEMS.size();i++)if(UgcCatalog.ITEMS.get(i).equalsIgnoreCase(text)){id=i;break;}}}if(id<0||id>=19)throw new IllegalArgumentException("Unknown UGC item: "+value);return id;}
    public static String authoredMode(int item,String target){item(item);return item==3?"oc":item>=4?target(target):"nor";}
    public record Placement(int x,int y,int z,int item,String mode){
        public Placement{if(x<0||x>=512||y<0||y>=512||z<0||z>=256)throw new IllegalArgumentException("UGC entity outside world");UgcProject.item(item);mode=mode.strip().equalsIgnoreCase("nor")?"nor":target(mode);}
        public Map<String,Object> sidecar(){return ordered("position",List.of(x,y,z),"mode",mode,"item",UgcCatalog.ITEMS.get(item));}
    }
    public record Objective(String id,int value,int minimum,int maximum,int priority){public boolean complete(){return value>=minimum&&value<=maximum;}}
    public record Validation(String mode,List<Objective> objectives){public Validation{objectives=List.copyOf(objectives);}public boolean complete(){return objectives.stream().allMatch(Objective::complete);}}
    private record Requirement(String id,int min,int max,int priority,List<Integer> items){}
    private static Requirement requirement(String name,int min,int max,int priority,Integer...items){return new Requirement("UGC_OBJECTIVE_"+name,min,max,priority,List.of(items));}
    private static final Requirement SPAWN1=requirement("TEAM1_SPAWN_POINTS",1,10,1,7,8,9),SPAWN2=requirement("TEAM2_SPAWN_POINTS",1,10,1,4,5,6),BASE1=requirement("TEAM1_ZONE",1,1,2,13,14,15),BASE2=requirement("TEAM2_ZONE",1,1,2,10,11,12);
    private String title,description,author,baseplate,targetMode,skybox="";private List<List<Integer>> groundColors=List.of();private List<String> tags=List.of("map","tdm");private Integer prefabSet;private BigInteger handle=new BigInteger("18446744073709551615");private boolean overhead,modified=true;
    private final ArrayList<Placement> placements=new ArrayList<>();
    public UgcProject(String title,String description,String author,String baseplate,String targetMode){this.title=clean(title,"Untitled UGC",80);this.description=clean(description,"Undescribed UGC",512);this.author=clean(author,"Unknown",80);this.baseplate=terrain(baseplate).stem;this.targetMode=target(targetMode);}
    private static String clean(String s,String fallback,int limit){s=s.replace("\0","").strip();if(s.isEmpty())s=fallback;return s.substring(0,s.offsetByCodePoints(0,Math.min(limit,s.codePointCount(0,s.length()))));}
    public String title(){return title;}public String description(){return description;}public String author(){return author;}public String baseplate(){return baseplate;}public String targetMode(){return targetMode;}public String skybox(){return skybox;}public Integer prefabSet(){return prefabSet;}public boolean overhead(){return overhead;}public boolean modified(){return modified;}public BigInteger handle(){return handle;}public List<String> tags(){return tags;}public List<List<Integer>> groundColors(){return groundColors;}public List<Placement> placements(){return List.copyOf(placements);}
    public Terrain terrain(){return terrain(baseplate);}public Terrain prefabTerrain(){return prefabSet==null?terrain():terrain(PALETTES.get(prefabSet));}
    public void description(String value){description=clean(value,"Undescribed UGC",512);modified=true;}
    public void author(String value){author=clean(value,"Unknown",80);modified=true;}
    public void targetMode(String value){targetMode=target(value);modified=true;}
    public void prefabSet(Integer value){if(value!=null&&(value<0||value>=6))throw new IllegalArgumentException("Prefab palette must be 0..5");prefabSet=value;modified=true;}
    public boolean title(String value){if(value.isBlank()||value.codePointCount(0,value.length())>80||value.indexOf('\0')>=0||value.indexOf('\n')>=0||value.indexOf('\r')>=0)return false;title=value.strip();modified=true;return true;}
    public void skybox(String value){skybox=Objects.requireNonNull(value);modified=true;}
    public void overhead(boolean value){overhead=value;modified=true;}
    public void touch(){modified=true;}
    public void groundColors(List<? extends List<? extends Number>> values){var out=new ArrayList<List<Integer>>();for(var row:values.subList(0,Math.min(32,values.size()))){if(row.size()!=4)throw new IllegalArgumentException("Ground colors need RGBA");out.add(row.stream().map(n->integer(n)&255).toList());}groundColors=List.copyOf(out);modified=true;}
    public Optional<Placement> place(int x,int y,int z,int item){return place(new Placement(x,y,z,item,authoredMode(item,targetMode)));}
    public Optional<Placement> place(Placement p){if(placements.size()>=MAX_ENTITIES||placements.contains(p))return Optional.empty();placements.add(p);modified=true;return Optional.of(p);}
    public Optional<Placement> remove(int x,int y,int z,Integer item){if(item!=null)item(item);int best=-1;int[] rank=null;for(int i=placements.size()-1;i>=0;i--){var p=placements.get(i);long dx=(long)p.x-x,dy=(long)p.y-y,dz=(long)p.z-z;if(Math.abs(dx)>1||Math.abs(dy)>1||Math.abs(dz)>1)continue;long d=dx*dx+dy*dy+dz*dz;if(d>1)continue;int[] r={p.mode.equals("nor")||p.mode.equals(targetMode)?0:1,item==null||p.item==item?0:1,(int)d,-i};if(rank==null||Arrays.compare(r,rank)<0){rank=r;best=i;}}if(best<0)return Optional.empty();modified=true;return Optional.of(placements.remove(best));}
    public Validation validation(){return validation(targetMode);}
    public Validation validation(String target){String mode=target(target);var requirements=new ArrayList<>(List.of(requirement("AMMOCRATE_SPAWNS",2,25,4,1),requirement("HEALTHCRATE_SPAWNS",2,25,4,0),requirement("BLOCKCRATE_SPAWNS",2,25,4,2),SPAWN1,SPAWN2));switch(mode){case "ctf","dem"->{requirements.add(BASE1);requirements.add(BASE2);}case "tc","mh","dia"->requirements.add(requirement(mode.toUpperCase(Locale.ROOT)+"_NEUTRAL_ZONES",2,mode.equals("dia")?5:10,3,16,17,18));case "oc"->{requirements.add(BASE2);requirements.add(requirement("BOMB_SPAWNS",1,5,3,3));}default->{}}var rows=new ArrayList<Objective>();for(var r:requirements){int n=(int)placements.stream().filter(p->r.items.contains(p.item)&&(p.mode.equals("nor")||p.mode.equals(mode))).count();rows.add(new Objective(r.id,n,r.min,r.max,r.priority));}rows.sort(Comparator.comparingInt(Objective::priority));return new Validation(mode,rows);}
    public List<String> publishableModes(){return MODES.stream().filter(m->validation(m).complete()).toList();}
    public Map<String,Object> sidecar(){var fresh=new ArrayList<String>();fresh.add("map");fresh.addAll(publishableModes());tags=List.copyOf(fresh);return ordered("use_overhead_image",overhead,"description",description,"title",title,"ugc_entities",placements.stream().map(Placement::sidecar).toList(),"ground_colors",groundColors,"skybox_name",skybox,"aos_ugc_handle",handle,"author",author,"baseplate",baseplate,"modified_since_publish",modified,"tags",tags,"ugc_target_mode",targetMode,"prefab_set",prefabSet);}
    public String json(){return ProjectJson.encode(sidecar());}
    public static UgcProject parse(String text,String fallbackTitle,String override){if(text.startsWith("\ufeff"))text=text.substring(1);Object raw=MetadataDocument.json(text);if(!(raw instanceof Map<?,?> data))throw new IllegalArgumentException("UGC sidecar root must be object");var entities=list(data.get("ugc_entities"),List.of());if(entities.size()>MAX_ENTITIES)throw new IllegalArgumentException("Too many UGC entities");var tags=list(data.get("tags"),List.of()).stream().map(String::valueOf).map(s->s.strip().toLowerCase(Locale.ROOT)).toList();String stored=string(data,"ugc_target_mode","").strip().toLowerCase(Locale.ROOT);String mode=override!=null?override:MODES.contains(stored)?stored:tags.stream().filter(MODES::contains).findFirst().orElse("tdm");var p=new UgcProject(string(data,"title",fallbackTitle),string(data,"description","Undescribed UGC"),string(data,"author","Unknown"),string(data,"baseplate","GrasslandBaseplate"),mode);
        for(var v:entities){if(!(v instanceof Map<?,?> row))throw new IllegalArgumentException("Invalid UGC entity");var pos=list(row.get("position"),null);if(pos.size()!=3)throw new IllegalArgumentException("UGC position needs three numbers");p.place(new Placement(integer(pos.get(0)),integer(pos.get(1)),integer(pos.get(2)),item(row.get("item")),string(row,"mode","nor")));}
        var colors=new ArrayList<List<Number>>();for(var v:list(data.get("ground_colors"),List.of()).stream().limit(32).toList()){var row=list(v,null);var c=new ArrayList<Number>();for(var n:row)c.add(integer(n));colors.add(c);}p.groundColors(colors);p.skybox=string(data,"skybox_name","");p.handle=new BigInteger(string(data,"aos_ugc_handle","18446744073709551615"));Object palette=data.get("prefab_set");if(palette!=null){if(!(palette instanceof Long||palette instanceof BigInteger))throw new IllegalArgumentException("Prefab palette must be integer");p.prefabSet(integer(palette));}p.overhead=truth(data.get("use_overhead_image"),false);p.modified=truth(data.get("modified_since_publish"),true);var normalized=new LinkedHashSet<String>();for(var t:tags)if(!t.isBlank())normalized.add(t);if(!normalized.contains("map")){var copy=new LinkedHashSet<String>();copy.add("map");copy.addAll(normalized);normalized=copy;}p.tags=List.copyOf(normalized);return p;}
    private static boolean truth(Object v,boolean fallback){return v==null?fallback:v instanceof Boolean b?b:v instanceof Number n?n.doubleValue()!=0:v instanceof String s?!s.isEmpty():v instanceof Collection<?> c?!c.isEmpty():true;}
    private static String string(Map<?,?> m,String key,String fallback){return m.containsKey(key)?String.valueOf(m.get(key)):fallback;}
    private static List<?> list(Object v,List<?> fallback){if(v==null&&fallback!=null)return fallback;if(v instanceof List<?> l)return l;throw new IllegalArgumentException("Expected UGC array");}
    private static int integer(Object v){if(v instanceof Number n){double d=n.doubleValue();if(!Double.isFinite(d)||d<Integer.MIN_VALUE||d>Integer.MAX_VALUE)throw new IllegalArgumentException("UGC integer out of range");return n.intValue();}try{return Integer.parseInt(String.valueOf(v).strip());}catch(NumberFormatException e){throw new IllegalArgumentException("Invalid UGC integer",e);}}
    private static Map<String,Object> ordered(Object...kv){var out=new LinkedHashMap<String,Object>();for(int i=0;i<kv.length;i+=2)out.put((String)kv[i],kv[i+1]);return Collections.unmodifiableMap(out);}
    public static String slug(String value){String s=value.strip().replaceAll("[^A-Za-z0-9_-]+","_").replaceAll("^[_-]+|[_-]+$","");if(s.isEmpty())throw new IllegalArgumentException("UGC project name needs a letter or digit");return s.substring(0,Math.min(64,s.length()));}
}
